arguments.command:
cd /workspace && python3 - << 'EOF'
p='src/image_validate.cpp'
lines=open(p).read().split('\n')
out=[]
for i,l in enumerate(lines):
    if 'return false;' in l:
        txt=l.strip().replace('return false;','').strip()
        if not txt:
            # look at previous line for context
            txt = lines[i-1].strip() if i>0 else ''
        txt = txt.replace('"',"'")[:70]
        indent = l[:len(l)-len(l.lstrip())]
        l = '%sreturn fail("%d: %s");' % (indent, i+1, txt)
    out.append(l)
s='\n'.join(out)
s=s.replace("""struct Validator {
    const ImageData* d = nullptr;""","""std::string scamp_validate_error;

struct Validator {
    const ImageData* d = nullptr;""")
s=s.replace("""    bool run();
    bool shape();""","""    bool fail(const char* where) {
        scamp_validate_error = where;
        return false;
    }
    bool run();
    bool shape();""")
s=s.replace("""bool validate_image(const ImageData& d, ParsedImage& out) {
    Validator v;""","""bool validate_image(const ImageData& d, ParsedImage& out) {
    scamp_validate_error.clear();
    Validator v;""")
s=s.replace('#include <deque>','#include <deque>\n#include <string>')
open(p,'w').write(s)
h=open('src/image_validate.h').read()
h=h.replace("""bool validate_image(const ImageData& d, ParsedImage& out);""","""bool validate_image(const ImageData& d, ParsedImage& out);

/* Last validation failure location (diagnostics only). */
extern std::string scamp_validate_error;""")
h=h.replace('#include "image.hpp"','#include "image.hpp"\n#include <string>')
open('src/image_validate.h','w').write(h)
print(s.count('return fail('))
EOF
grep -n "fail(" src/image_validate.cpp | head -5; python3 build.py 2>&1 | tail -5
